function buildLocale(locale: 'de' | 'en' | 'fr') {
  const baseRanks = baseClanRanks[locale] as Record<string, string>
  return {
    clans: {
      ...baseClanNames[locale],
      ...sharedClans,
    },
    ranks: {
      ...baseRanks,
      ...buildHunterGathererAliases(baseRanks),
      ...sharedRanks,
    },
    potentials: {
      ...sharedPotentials,
    },
  }
}

export const clanMessages = {
  de: buildLocale('de'),
  en: buildLocale('en'),
  fr: buildLocale('fr'),
}
